// Builds the MCP App widget (docs/CONTRACT.md section 7), as cobalt's scripts/build-widgets.mjs: inlines
// src/mcp/widgets/ (bridge.js + main.js + style.css into shell.html) as one self-contained page, minified with esbuild,
// and writes src/mcp/widgets.generated.ts. `--check` writes nothing and exits 1 when the generated file is stale.
//   node scripts/build-widgets.mjs [--check]
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src/mcp/widgets");
const out = join(root, "src/mcp/widgets.generated.ts");

// scope order: the bridge first, then the view that uses it
const JS = ["bridge.js", "main.js"];
const read = (f) => readFileSync(join(src, f), "utf8");

export function buildPage() {
    const js = `"use strict";(()=>{\n${JS.map(read).join("\n")}\n})();`;
    const code = transformSync(js, { minify: true, target: "es2020", loader: "js", legalComments: "none" }).code.trim();
    const css = transformSync(read("style.css"), { minify: true, loader: "css" }).code.trim();
    // a "</script>" or "</style>" inside the code would end the tag early
    if (/<\/(script|style)/i.test(code + css)) throw new Error("bundle contains a closing script/style tag");
    return read("shell.html")
        .trim()
        .replace("/*CSS*/", () => css)
        .replace("/*JS*/", () => code.replace(/<!--/g, "<\\!--"));
}

export function buildFile() {
    const html = buildPage();
    return `// GENERATED by scripts/build-widgets.mjs from src/mcp/widgets/. Do not edit: run \`npm run widgets\`.
export const NOTES_WIDGET_URI = "ui://capystack/notes";

export type Widget = { name: string; uri: string; title: string; html: string };

export const WIDGETS: Widget[] = [
    {
        name: "notes",
        uri: NOTES_WIDGET_URI,
        title: "capystack: notes",
        html: ${JSON.stringify(html)},
    },
];
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
    const next = buildFile();
    if (process.argv.includes("--check")) {
        if (!existsSync(out) || readFileSync(out, "utf8") !== next) {
            console.error("src/mcp/widgets.generated.ts is stale: run `npm run widgets`");
            process.exit(1);
        }
        console.log("widgets.generated.ts is up to date");
    } else {
        writeFileSync(out, next);
        console.log(`wrote src/mcp/widgets.generated.ts (${(Buffer.byteLength(next) / 1024).toFixed(1)} KB)`);
    }
}
